def solve(ops):
    from collections import deque
    queue = deque()
    out = []
    for op in ops:
        if op[0] == "enq":
            queue.append(op[1])
            out.append("ok")
        elif not queue:
            out.append("error")
        else:
            out.append(queue.popleft())
    return out
